CREATE TABLE "ManagerIntervention" ("id" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"sourceKey" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"severity" TEXT NOT NULL,"score" INTEGER NOT NULL DEFAULT 0,"applicantId" TEXT,"agentId" TEXT,"assignedToId" TEXT,"createdById" TEXT NOT NULL,"deadline" TIMESTAMP(3),"note" TEXT,"resolution" TEXT,"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ManagerIntervention_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "ManagerIntervention_agencyId_sourceKey_key" ON "ManagerIntervention"("agencyId","sourceKey");CREATE INDEX "ManagerIntervention_agencyId_status_deadline_idx" ON "ManagerIntervention"("agencyId","status","deadline");
